css:
#dyn-message-theme[data-theme="message-geico-marathon"],
#dyn-message-theme[data-theme="message-geico-marathon"] .dyn-fit-stage {
  background: var(--background, #005eac);
}
#dyn-message-theme[data-theme="message-geico-marathon"] .board {
  position: absolute;
  inset: 0;
  background: var(--background, #005eac);
  container-type: size;
  overflow: hidden;
  color: #fff;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .bar {
  position: absolute;
  z-index: 4;
  top: 4.5cqh;
  right: 4.5cqw;
  display: flex;
  justify-content: flex-end;
}

#dyn-message-theme[data-theme="message-geico-marathon"] .logo {
  width: 22cqw;
  height: auto;
  display: block;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .copy {
  position: absolute;
  z-index: 3;
  left: 8cqw;
  right: 8cqw;
  top: 16cqh;
  bottom: 14cqh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  opacity: 0;
  transform: translateY(1.4cqh);
}
#dyn-message-theme[data-theme="message-geico-marathon"].on .copy {
  opacity: 1;
  transform: none;
  transition: opacity 0.45s ease, transform 0.45s ease;
}
#dyn-message-theme[data-theme="message-geico-marathon"][data-motion="drift"].on .copy {
  transition-duration: 0.9s;
}
#dyn-message-theme[data-theme="message-geico-marathon"][data-motion="fizz"].on .copy {
  transition-duration: 0.28s;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .racer,
#dyn-message-theme[data-theme="message-geico-marathon"] .from {
  margin: 0;
  color: var(--secondary, #ffffff);
  font-family: Caveat, cursive;
  font-weight: 700;
  line-height: 0.95;
  max-width: 100%;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .racer {
  font-size: 13cqw;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .from {
  font-size: 6.5cqw;
  margin-top: 0.12em;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .sign {
  margin: 0.04em 0 0;
  color: var(--primary, #d6f25c);
  font-family: "Barlow Condensed", "Arial Narrow", sans-serif;
  font-weight: 700;
  font-size: 8.2cqw;
  line-height: 0.95;
  max-width: 100%;
  transition: opacity 0.28s ease;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .glyph {
  position: absolute;
  z-index: 2;
  left: 1.2cqw;
  bottom: 0.4cqh;
  width: 22cqw;
  height: auto;
  display: block;
  pointer-events: none;
  transition: opacity 0.28s ease;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .sign.is-fading,
#dyn-message-theme[data-theme="message-geico-marathon"] .glyph.is-fading {
  opacity: 0;
}
#dyn-message-theme[data-theme="message-geico-marathon"] .slot-logo,
#dyn-message-theme[data-theme="message-geico-marathon"] .slot-qr {
  display: none;
}
#dyn-message-theme[data-theme="message-geico-marathon"].dyn-show-logo .slot-logo {
  display: block;
  position: absolute;
  z-index: 5;
  top: 4cqh;
  left: 4cqw;
  width: 14cqw;
}

#dyn-message-theme[data-theme="message-geico-marathon"].dyn-show-qr .slot-qr {
  display: block;
  position: absolute;
  z-index: 5;
  right: 3cqw;
  bottom: 4cqh;
  width: 12cqw;
}
#dyn-message-theme[data-theme="message-geico-marathon"].no-racer .racer,
#dyn-message-theme[data-theme="message-geico-marathon"].no-name .from {
  display: none;
}
